<?php
declare(strict_types=1);
function productStatusResponse(int $status,array $payload):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
if(($_SERVER['REQUEST_METHOD']??'')!=='POST')productStatusResponse(405,['success'=>false,'code'=>'method_not_allowed']);require_once dirname(__DIR__,3).'/includes/auth.php';$user=currentUser();if($user===null)productStatusResponse(401,['success'=>false,'code'=>'authentication_required']);$raw=file_get_contents('php://input');try{$body=json_decode(is_string($raw)?$raw:'',true,8,JSON_THROW_ON_ERROR);}catch(Throwable){productStatusResponse(400,['success'=>false,'code'=>'invalid_json']);}if(!is_array($body)||array_keys($body)!==['csrf_token','productId','action'])productStatusResponse(400,['success'=>false,'code'=>'invalid_fields']);if(!verifyChichejCsrfToken(is_string($body['csrf_token'])?$body['csrf_token']:null))productStatusResponse(403,['success'=>false,'code'=>'invalid_csrf']);$id=is_string($body['productId'])?trim($body['productId']):'';$action=is_string($body['action'])?trim($body['action']):'';if(!preg_match('/^[A-Za-z0-9_-]{1,150}$/',$id)||!in_array($action,['activar','desactivar','agotar','disponible'],true))productStatusResponse(422,['success'=>false,'code'=>'invalid_action']);
require_once dirname(__DIR__,3).'/services/AdminAuthorizationService.php';require_once dirname(__DIR__,3).'/services/ProductService.php';try{$admin=(new AdminAuthorizationService())->requireFreshAdmin($user);$change=(new ProductService())->changeStatus($id,$action,$admin);productStatusResponse(200,['success'=>true,'change'=>$change]);}catch(AdminAuthorizationException){productStatusResponse(403,['success'=>false,'code'=>'admin_not_authorized']);}catch(ProductNotFoundException){productStatusResponse(404,['success'=>false,'code'=>'not_found']);}catch(ProductConflictException){productStatusResponse(409,['success'=>false,'code'=>'conflict']);}catch(Throwable $e){error_log('Product status failed: '.$e->getMessage());productStatusResponse(503,['success'=>false,'code'=>'product_unavailable']);}
